package app.manga.library;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.security.Principal;import java.time.Instant;import java.util.*;import app.manga.user.UserRepository;import org.springframework.http.HttpStatus;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1")public class LibraryController{private final LibraryRepository repo;private final UserRepository users;public LibraryController(LibraryRepository r,UserRepository u){repo=r;users=u;}private UUID uid(Principal p){return users.findByEmail(p.getName()).orElseThrow().getId();}public record Item(@NotBlank String provider,@Positive long externalMangaId,@NotBlank@Size(max=500)String titleSnapshot,String coverUrlSnapshot,@NotBlank String readingStatus,Instant addedAt,Instant updatedAt){}public record StatusBody(@NotBlank String readingStatus){}public record SyncBody(@NotEmpty@Size(max=200)List<@Valid Item> items){}
 @GetMapping("/library")public Object list(Principal p){return Map.of("data",repo.findAllByUserIdOrderByUpdatedAtDesc(uid(p)).stream().map(LibraryController::dto).toList());}
 @PostMapping("/library")public Object add(Principal p,@Valid@RequestBody Item b){return Map.of("data",dto(upsert(uid(p),b)));}
 @PatchMapping("/library/{id}")public Object status(Principal p,@PathVariable UUID id,@Valid@RequestBody StatusBody b){if(!statuses().contains(b.readingStatus()))throw new IllegalArgumentException("Status membaca tidak valid.");var e=repo.findByIdAndUserId(id,uid(p)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));e.changeStatus(b.readingStatus());return Map.of("data",dto(repo.save(e)));}
 @DeleteMapping("/library/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(Principal p,@PathVariable UUID id){var e=repo.findByIdAndUserId(id,uid(p)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));repo.delete(e);}
 @PostMapping("/sync/guest-library")@Transactional public Object sync(Principal p,@Valid@RequestBody SyncBody b){UUID user=uid(p);int done=0;for(Item i:b.items()){validate(i);upsert(user,i);done++;}return Map.of("data",Map.of("succeeded",done,"failed",0));}
 private LibraryEntry upsert(UUID u,Item i){validate(i);String provider=i.provider().toUpperCase(Locale.ROOT);var old=repo.findByUserIdAndProviderAndExternalMangaId(u,provider,i.externalMangaId());if(old.isPresent()){LibraryEntry e=old.get();e.merge(new LibraryEntry(u,provider,i.externalMangaId(),i.titleSnapshot(),safeCover(i.coverUrlSnapshot()),i.readingStatus(),i.addedAt(),i.updatedAt()));return repo.save(e);}return repo.save(new LibraryEntry(u,provider,i.externalMangaId(),i.titleSnapshot(),safeCover(i.coverUrlSnapshot()),i.readingStatus(),i.addedAt(),i.updatedAt()));}
 private void validate(Item i){if(!i.provider().equalsIgnoreCase("JIKAN"))throw new IllegalArgumentException("Provider tidak didukung.");if(!statuses().contains(i.readingStatus()))throw new IllegalArgumentException("Status membaca tidak valid.");safeCover(i.coverUrlSnapshot());}
 private String safeCover(String s){if(s==null)return null;try{var u=java.net.URI.create(s);if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||s.length()>2000)throw new IllegalArgumentException("URL cover tidak valid.");return s;}catch(Exception e){throw new IllegalArgumentException("URL cover tidak valid.");}}
 private static Set<String>statuses(){return Set.of("READING","PLAN_TO_READ","COMPLETED","ON_HOLD","DROPPED");}
 private static Object dto(LibraryEntry e){var m=new LinkedHashMap<String,Object>();m.put("id",e.getId());m.put("provider",e.getProvider());m.put("externalMangaId",e.getExternalMangaId());m.put("titleSnapshot",e.getTitleSnapshot());m.put("coverUrlSnapshot",e.getCoverUrlSnapshot());m.put("readingStatus",e.getReadingStatus());m.put("addedAt",e.getAddedAt());m.put("updatedAt",e.getUpdatedAt());return m;}
}
